    ∀ᶠ t : ℕ in atTop, r ^ t ≤ c / (Real.log t) ^ k

theorem exists_embedding_of_coord_lt (p : ProbabilityVector ι) {i j k : ι}
    (hij : p.coord i < p.coord j) (hjk : p.coord j < p.coord k) :
