private theorem integral_kernelRemainderDensity (a : ℝ) (ha : 0 < a) (ha1 : a ≠ 1) :
    (∫ v in (0 : ℝ)..1, kernelRemainderDensity a v) =
      (remainderPrimitive a a - remainderPrimitive a 1) / (a - 1) ^ 7

theorem CutoffHeavyCandidateForm.objective_le {t : ℕ} {h : ℝ} {p : ProbabilityVector ι}
    (hp : CutoffHeavyCandidateForm t h p) (hh : 0 < h) :
