    HasSum (fun i => if i ∈ s then g i else f i) (a + ∑ i ∈ s, (g i - f i))

theorem phaseUpper_le_adjacent_crossing {h : ℝ} {m : ℕ}
    (hh : 0 < h) (hm : entropySupportIndex h ≤ m) (hm2 : 2 ≤ m) :
    phaseUpper h m hh hm hm2 ≤ (heavyCrossing h m (m + 1) : WithTop ℝ)

private theorem hasDerivAt_cutoffAux (s z : ℝ) {u : ℝ} (hu : 0 < u) (hu1 : u < 1) :
