    (Function.support (candidateVector m z hm ⟨hz.1.le,hz.2.le⟩).coord).ncard = m+1

theorem localMax_of_entropy_slack [Fintype ι] (p : ProbabilityVector ι) {t : ℕ} {h : ℝ}
    (hp : LocalMaximizer t h p) (hslack : p.entropy < ENNReal.ofReal h) :
    IsLocalMax (fun q : ProbabilityVector ι => q.objective t) p

theorem coord_pos_of_entropy_slack (p : ProbabilityVector ι) {t : ℕ} {h : ℝ}
    (ht : 1 ≤ t) (hp : LocalMaximizer t h p) (hslack : p.entropy < ENNReal.ofReal h) (i : ι) :
    0 < p.coord i

theorem deriv_eq_of_entropy_slack [Fintype ι] (p : ProbabilityVector ι) {t : ℕ} {h : ℝ}
    (ht : 1 ≤ t) (hp : LocalMaximizer t h p) (hslack : p.entropy < ENNReal.ofReal h) (i j : ι) :
    deriv (missingMassTerm t) (p.coord i) = deriv (missingMassTerm t) (p.coord j)

theorem repeated_pair_weighted_bound {ι : Type*} (p : ProbabilityVector ι) {t : ℕ} {h : ℝ}
    (ht : 1 ≤ t) (hp : LocalMaximizer t h p) (e : Fin 3 ↪ ι) {q z : ℝ}
    (hq : 0 < q) (hqz : q < z) (hbase : (fun i => p.coord (e i)) = repeatedPairBase q z) :
    q * deriv (deriv (missingMassTerm t)) q ≤
      (deriv (missingMassTerm t) z - deriv (missingMassTerm t) q) / (Real.log z - Real.log q)

private theorem entropy_velocity_sum (x : Triple) (h0 : 0 < x 0) (h01 : x 0 < x 1) (h12 : x 1 < x 2) (b : ℝ) :
    (∑ i : Fin 3, (-Real.log (x i) - 1) * ((-(x i) + b) / rootDenom x i)) =
      Curvature.I1 (x 0) (x 1) (x 2) + b * Curvature.I0 (x 0) (x 1) (x 2)

private theorem fderiv_apply_of_direction {H : Triple → ℝ} {c w : Triple} {b : ℝ}
    (hH : DifferentiableAt ℝ H c)
    (hd : HasDerivAt (fun r : ℝ => H (c + r • w)) b 0) : fderiv ℝ H c w = b

private theorem directionalPartial_eq_fderiv {H : Triple → ℝ} {c : Triple}
    (hH : DifferentiableAt ℝ H c) (w : Triple) :
    deriv (fun r : ℝ => H (c + r • w)) 0 = fderiv ℝ H c w

theorem StationaryFiniteCandidateForm.feasible {m t : ℕ} {hm : 0 < m} {h : ℝ}
    {p : ProbabilityVector (Fin (m+1))} (hp : StationaryFiniteCandidateForm hm t h p) (ht : 1 ≤ t) :
