theorem no_two_repeated_sizes_embedded (p : ProbabilityVector ι) {t : ℕ} {h : ℝ}
    (ht : 1 ≤ t) (hp : LocalMaximizer t h p) (e : Fin 4 ↪ ι) {x y : ℝ}
