theorem heavy_candidate_root_unique {m : ℕ} (hm : 0 < m) {h z w : ℝ}
    (hz : z ∈ Ioo (1 / ((m : ℝ) + 1)) 1) (hw : w ∈ Ioo (1 / ((m : ℝ) + 1)) 1)
    (hez : branchEntropy m z = h) (hew : branchEntropy m w = h) : z = w

